void TBossPakkun::rumblePad(int type, const JGeometry::TVec3<f32>& position)
{
	if (!SMS_IsMarioTouchGround4cm())
		return;

	JGeometry::TVec3<f32> delta = SMS_GetMarioPos();
	delta -= position;
	f32 power = (3000.0f - delta.length()) / 1000.0f;

	if (power < 0.0f)
		return;
	if (power > 1.0f)
		power = 1.0f;

	switch (type) {
	case 0:
		power *= 0.4f;
		break;
	case 1:
		power *= 0.7f;
		break;
	case 2:
		break;
	}

	unk1C8 = power;
	SMSRumbleMgr->start(8, &unk1C8);
}

void TBossPakkun::showMessage(u32 message)
{
	u32 index = message - 0xe0000;
