	if (actor->checkCurBckFromIndex(20)) {
		f32 c = MsCos(boss->mRotation.y);
		JGeometry::TVec3<f32> wind(MsSin(boss->mRotation.y), 0.0f, c);
		gpModelWaterManager->wind(wind);
