	}

	if (mSpine->getCurrentNerve() != &TNerveGessoPunch::theNerve()
	    && mSpine->getCurrentNerve() != &TNerveGessoFreeze::theNerve()
	    && mSpine->getCurrentNerve() != &TNerveSmallEnemyDie::theNerve()) {
		mAttackCooldown = 1;
