			if (mIsRightSideUp) {
				JGeometry::TVec3<f32> local_1c(
				    mPosition.x - SMS_GetMarioPos().x, 0.0f,
				    mPosition.z - SMS_GetMarioPos().z);

				if (local_1c.x == 0.0f && local_1c.z == 0.0f)
