				local_1c.x *= hitWaterSpXZ;
				if (abs(local_1c.x) < 5.0f) {
					if (local_1c.x > 0.0f)
						local_1c.x = 5.0f;
					else
						local_1c.x = -5.0f;
				}
				local_1c.z *= hitWaterSpXZ;
				if (abs(local_1c.z) < 5.0f) {
					if (local_1c.z > 0.0f)
						local_1c.z = 5.0f;
					else
						local_1c.z = -5.0f;
				}
				local_1c.y *= hitWaterSpY;
				mVelocity = local_1c;
				mPosition.y += 2.0f;
				onLiveFlag(LIVE_FLAG_AIRBORNE);
			}

