		} else {
			self->unk1DC.y *= 0.3f;
			self->mPosition.y += 2.0f;
			self->onLiveFlag(LIVE_FLAG_AIRBORNE);
			self->setVelocity(self->unk1DC);
		}
	} else if (self->unkF4.unk0 == (THitActor*)gpMarioAddress) {
		self->walkToCurPathNode(0.0f, self->getTurnSpeed(), 0.0f);
