DEFINE_NERVE(TNerveGessoLand, TLiveActor)
{
	TGesso* self = (TGesso*)spine->getBody();

	if (spine->getTime() == 0)
		self->setBckAnm(14);

	if (self->checkCurAnmEnd(0)) {
