DEFINE_NERVE(TNerveGessoTurn, TLiveActor)
{
	TGesso* self = (TGesso*)spine->getBody();

	if (spine->getTime() < 2) {
		self->turnIn();
	} else if (self->turning()) {
		self->turnOut();
		return true;
	}

	return false;
}

