	}

	case 13: {
		param_1->getParent()->readPortAppDirect(8, &local_26);
		u16 uVar3 = local_26 > smWaterFilter ? local_26 : smWaterFilter;
		param_1->writePortAppDirect(0xe, uVar3);
		param_1->writePortAppDirect(0xf, uVar3);
		return 0x7f - uVar3;
	}

	case 0: {
