// TODO: frame is 0x30 instead of 0x38; StageUtil.hpp's GC2D tables also
// shift the throw and balloon constants in .sdata2.
BOOL TEggYoshi::receiveMessage(THitActor* sender, u32 message)
{
	if (message == HIT_MESSAGE_TAKE) {
		hold((TTakeActor*)sender);
		return TRUE;
	}

	if (message == HIT_MESSAGE_THROWN || message == HIT_MESSAGE_DETACH) {
		mVelocity.y = 10.0f;
		offLiveFlag(LIVE_FLAG_UNK10);
		mState = 0xF;
		return TRUE;
	}

	if (message == HIT_MESSAGE_UNK10) {
		JGeometry::TVec3<f32> v = getVelocity();
		makeObjAppeared();
		mVelocity.y = v.y;
		offLiveFlag(LIVE_FLAG_UNK10);
		decideRandomLoveFruit();
		startBalloonAnim();
		mState = STATE_NORMAL;
		return TRUE;
	}

	if (message == HIT_MESSAGE_PUT) {
		makeObjAppeared();
		decideRandomLoveFruit();
		startBalloonAnim();
	}

	return FALSE;
}

