    , mContainedNozzleItem(nullptr)
    , unk150(0.0f)
    , unk154(0.0f)
    , mContainedNozzleName(nullptr)
    , unk15C(true)
    , unk166(false)
{
	unk15E.r = 0xFF;
	unk15E.g = 0xFF;
	unk15E.b = 0xFF;
	unk15E.a = 0x64;
}

