			return changePlayerDropping(MARIO_STATUS_CATCH_STOP, 0);
	} else {
		mStatusTimer++;
	}

	if (doSliding(getSlideStopNormal()))
		return changePlayerStatus(arg0, 0, false);

	slippingBasic(arg0, arg1, arg2);
