						mParticleVelocitySOA[i].x = 0.0f;
						mParticleVelocitySOA[i].y = 0.0f;
						mParticleVelocitySOA[i].z = 0.0f;

						setFlagBottom4Bits(i, 1);
						continue;
					}
				}
			}

			setFlagBottom4Bits(i, 1);
		}
	}

	int r20 = -1;
	int r26 = -1;
	for (int i = 0; i < mParticleCount; ++i) {
		switch (mParticleFlagSOA[i] & 0xf) {
		case 1:
			mParticleLifetimeSOA[i] -= 1.0f;
			break;

		case 2: {
			if (mParticleLifetimeSOA[i] > unk5D68)
				mParticleLifetimeSOA[i] = unk5D68;
			SMSGetMSound()->startSoundSet(MSD_SE_PO_WT_DRY_UP,
			                              &mParticlePositionSOA[i], 0, 0.0f, 0,
			                              0, 4);

			splashGround(i); // TODO: probably wrong inline

			if (unk5D60 & 0x40) {
				if (r20 < 0) {
					r20 = i;
				} else {
					JGeometry::TVec3<f32> kek = vecBetweenParticles(i, r20);

					f32 max = unk5D88[6]
					          * (mParticleSizeSOA[i] + mParticleSizeSOA[r20]);

					if (kek.length() < max) {

						mParticleSizeSOA[r20]     = mParticleSizeSOA[i];
						mParticleLifetimeSOA[r20] = mParticleLifetimeSOA[i];
						mParticleLifetimeSOA[i]   = 0.0f;
					} else {
						r20 = i;
					}
				}
			}
			break;
		}
		case 3:
			if (mParticleLifetimeSOA[i] > unk5D6C)
				mParticleLifetimeSOA[i] = unk5D6C;

			splashWall(i); // TODO: probably wrong inline

			if (unk5D60 & 0x40) {
				if (r26 < 0) {
					r26 = i;
				} else {
					JGeometry::TVec3<f32> kek = vecBetweenParticles(i, r26);

					f32 max = unk5D88[6]
					          * (mParticleSizeSOA[i] + mParticleSizeSOA[r26]);

					if (kek.length() < max) {
						mParticleSizeSOA[r26]     = mParticleSizeSOA[i];
						mParticleLifetimeSOA[r26] = mParticleLifetimeSOA[i];
						mParticleLifetimeSOA[i]   = 0.0f;
					} else {
						r26 = i;
					}
				}
			}
			break;
		}
	}

	garbageCollect();
}

void TModelWaterManager::calcWorldMinMax()
{
	if (mParticleCount == 0) {
		unk5D70 = SMS_GetMarioPos();
		unk5D7C = SMS_GetMarioPos();

		unk5D70.x -= 1.0f;
		unk5D70.y -= 1.0f;
		unk5D70.z -= 1.0f;

		unk5D7C.x += 1.0f;
		unk5D7C.y += 1.0f;
		unk5D7C.z += 1.0f;
		return;
	}

	JGeometry::TVec3<f32> min;
	JGeometry::TVec3<f32> max;
	min.x = mParticlePositionSOA[0].x - 1.0f;
	min.y = mParticlePositionSOA[0].y - 1.0f;
	min.z = mParticlePositionSOA[0].z - 1.0f;
	max.x = 1.0f + mParticlePositionSOA[0].x;
	max.y = 1.0f + mParticlePositionSOA[0].y;
	max.z = 1.0f + mParticlePositionSOA[0].z;
	for (int i = 1; i < mParticleCount; ++i) {
		if (min.x > mParticlePositionSOA[i].x)
			min.x = mParticlePositionSOA[i].x;
		if (min.y > mParticlePositionSOA[i].y)
			min.y = mParticlePositionSOA[i].y;
		if (min.z > mParticlePositionSOA[i].z)
			min.z = mParticlePositionSOA[i].z;
		if (max.x < mParticlePositionSOA[i].x)
			max.x = mParticlePositionSOA[i].x;
		if (max.y < mParticlePositionSOA[i].y)
			max.y = mParticlePositionSOA[i].y;
		if (max.z < mParticlePositionSOA[i].z)
			max.z = mParticlePositionSOA[i].z;
	}

	unk5D70.x = min.x - 200.0f;
	unk5D70.y = min.y - 200.0f;
	unk5D70.z = min.z - 200.0f;

	unk5D7C.x = 200.0f + max.x;
	unk5D7C.y = 200.0f + max.y;
	unk5D7C.z = 200.0f + max.z;
}

void TModelWaterManager::calcDrawVtx(MtxPtr viewMtx)
{
	unk5D30->reset();

	for (int i = 0; i < mParticleCount; ++i) {
		if ((mParticleFlagSOA[i] & 0xf) != 1)
			continue;

		if (mParticleLifetimeSOA[i]
		    < mWaterParticleTypes[mParticleTypeSOA[i]]->mAlive.get()
		          - unk5D88[7]) {
			JGeometry::TVec3<f32> viewPos;
			MTXMultVec(viewMtx, &mParticlePositionSOA[i], &viewPos);

			if (!(viewPos.z > 0.0f) && !(viewPos.z < -unk5D28)) {
				JGeometry::TVec3<f32> viewVel;
				MTXMultVecSR(viewMtx, &mParticleVelocitySOA[i], &viewVel);

				viewVel *= mWaterParticleTypes[mParticleTypeSOA[i]]
				               ->mExtension.get();

				f32 lenSq = viewVel.x * viewVel.x + viewVel.y * viewVel.y;
				f32 size  = 1.414f * (0.5f * mParticleSizeSOA[i]);

				JGeometry::TVec3<f32> vtx[4];

				if (lenSq > 1.0f) {
					f32 len    = MsSqrtf(lenSq);
					f32 scale  = (1.0f / len) * size;
					f32 nx     = viewVel.x * scale;
					f32 ny     = viewVel.y * scale;
					f32 neg_nx = -nx;

					vtx[0].x = viewVel.x * unk5D18 + (viewPos.x + nx);
					vtx[0].y = viewVel.y * unk5D18 + (viewPos.y + ny);
					vtx[0].z = viewPos.z;

					vtx[1].x = viewPos.x + ny;
					vtx[1].y = viewPos.y + neg_nx;
					vtx[1].z = viewPos.z;

					vtx[2].x = (viewPos.x - nx) - viewVel.x * unk5D18;
					vtx[2].y = (viewPos.y - ny) - viewVel.y * unk5D18;
					vtx[2].z = viewPos.z;

					vtx[3].x = viewPos.x - ny;
					vtx[3].y = viewPos.y - neg_nx;
					vtx[3].z = viewPos.z;
				} else {
					vtx[0].x = viewPos.x - size;
					vtx[0].y = viewPos.y + size;
					vtx[0].z = viewPos.z;

					vtx[1].x = viewPos.x + size;
					vtx[1].y = viewPos.y + size;
					vtx[1].z = viewPos.z;

					vtx[2].x = viewPos.x + size;
					vtx[2].y = viewPos.y - size;
					vtx[2].z = viewPos.z;

					vtx[3].x = viewPos.x - size;
					vtx[3].y = viewPos.y - size;
					vtx[3].z = viewPos.z;
				}

				unk5D30->request(vtx);
			}
		}
	}

	unk5D30->setEnd();
}

void TModelWaterManager::calcVMMtxGround(MtxPtr param_1, f32 param_2,
                                         const JGeometry::TVec3<f32>& param_3,
                                         const JGeometry::TVec3<f32>& param_4,
                                         MtxPtr param_5)
{
	f32 sx    = param_2 * param_4.x;
	f32 sy    = param_2 * param_4.y;
	f32 ty    = param_4.y * 2.0f + param_3.y;
	f32 negSx = -sx;

	f32 tx    = param_4.x * 2.0f + param_3.x;
	f32 sz    = param_2 * param_4.z;
	f32 tz    = param_4.z * 2.0f + param_3.z;
	f32 negSz = -sz;

	for (int i = 0; i < 3; ++i) {
		f32 b         = param_1[i][1];
		f32 c         = param_1[i][2];
		f32 a         = param_1[i][0];
		f32 d         = param_1[i][3];
		param_5[i][0] = a * sy + b * negSx;
		param_5[i][1] = a * sx + b * sy + c * sz;
		param_5[i][2] = b * negSz + c * sy;
		param_5[i][3] = a * tx + b * ty + c * tz + d;
	}
}

void TModelWaterManager::calcVMMtxWall(MtxPtr param_1, f32 scale,
                                       const JGeometry::TVec3<f32>& param_3,
                                       const JGeometry::TVec3<f32>& param_4,
                                       MtxPtr param_5)
{
	f32 sx    = scale * param_4.x;
	f32 sz    = scale * param_4.z;
	f32 by    = param_3.y;
	f32 negSx = -sx;
	f32 tx    = param_4.x * 2.0f + param_3.x;
	f32 tz    = param_4.z * 2.0f + param_3.z;

	for (int i = 0; i < 3; ++i) {
		f32 b         = param_1[i][1];
		f32 c         = param_1[i][2];
		f32 a         = param_1[i][0];
		f32 d         = param_1[i][3];
		param_5[i][0] = a * sz + c * negSx;
		param_5[i][1] = b * scale;
		param_5[i][2] = a * sx + c * sz;
		param_5[i][3] = a * tx + b * by + c * tz + d;
	}
}

void TModelWaterManager::calcVMAll(MtxPtr param_1)
{
	for (int i = 0; i < mParticleCount; ++i) {
		if ((mParticleFlagSOA[i] & 0xf) != 2)
			continue;

		f32 f = mParticleSizeSOA[i]
		        * ((1.0f - unk5D88[5]) * (mParticleLifetimeSOA[i] / unk5D68)
		           + unk5D88[5]);
		calcVMMtxGround(param_1, f, mParticlePositionSOA[i],
		                unk2914[i]->getNormal(), unk2D14[i]);
	}

	for (int i = 0; i < mParticleCount; ++i) {
		if ((mParticleFlagSOA[i] & 0xf) != 3)
			continue;

		f32 f = mParticleSizeSOA[i]
		        * ((1.0f - unk5D88[5]) * (mParticleLifetimeSOA[i] / unk5D6C)
		           + unk5D88[5]);
