void TModelWaterManager::drawMirror(MtxPtr param_1)
{

	GXSetCurrentMtx(GX_PNMTX0);
	GXLoadPosMtxImm(param_1, GX_PNMTX0);
	GXSetCullMode(GX_CULL_NONE);
	GXSetNumChans(1);
